import{_ as s,o as a,c as t,a2 as n}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"manual/getting-started.md","filePath":"manual/getting-started.md"}'),i={name:"manual/getting-started.md"};function o(p,e,l,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="boot-the-iso" tabindex="-1">Boot the ISO <a class="header-anchor" href="#boot-the-iso" aria-label="Permalink to &quot;Boot the ISO&quot;">​</a></h2><p>The quickest path is QEMU with the release ISO:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512M -cdrom opencube-3.0.0.iso -boot d \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><p>Add <code>-vga std</code> for the graphical console (the TUI desktop needs it), or run headless with <code>-display none -serial mon:stdio</code>. On UEFI hosts add <code>-bios OVMF.fd</code> (see <a href="./boot-modes.html">boot-modes</a>).</p><p>The boot self-tests run, then the ring-3 shell greets you:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Open Cube OS User-space Shell (3.0.0)</span></span>
<span class="line"><span>ush&gt;</span></span></code></pre></div><h2 id="the-first-five-minutes" tabindex="-1">The first five minutes <a class="header-anchor" href="#the-first-five-minutes" aria-label="Permalink to &quot;The first five minutes&quot;">​</a></h2><p>The 8 merged apps are the intended surface - start with a wizard and watch it work:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; hwinfo            what hardware is in this machine</span></span>
<span class="line"><span>ush&gt; sysdiag           health snapshot, kernel log, memory picture</span></span>
<span class="line"><span>ush&gt; net-tool          address setup, WiFi scan, connectivity tests</span></span>
<span class="line"><span>ush&gt; update            the 5-step OTA wizard (network -&gt; A/B -&gt; DNS</span></span>
<span class="line"><span>                        -&gt; check -&gt; install)</span></span></code></pre></div><p>Press a digit to pick a menu item, <code>q</code> to quit. Destructive paths make you retype the target name and answer a bare <code>y</code>.</p><p>Two quick read-only tours:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool             disks, partitions, mounts</span></span>
<span class="line"><span>ush&gt; files                 browse, copy, edit</span></span></code></pre></div><h2 id="classic-commands-still-work" tabindex="-1">Classic commands still work <a class="header-anchor" href="#classic-commands-still-work" aria-label="Permalink to &quot;Classic commands still work&quot;">​</a></h2><p>Every historical command remains registered - the interface-freeze rule guarantees it (commands are added, never removed; the registry holds 284 programs):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lsblk                 same service call as disk-tool lsblk</span></span>
<span class="line"><span>ush&gt; checkupdate           same as update&#39;s step 4</span></span>
<span class="line"><span>ush&gt; help                  shell built-ins + registry summary</span></span>
<span class="line"><span>ush&gt; help -a               every registry entry, A-Z, tagged</span></span>
<span class="line"><span>ush&gt; help -w               grouped by domain (the mega group first)</span></span></code></pre></div><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; files                 the wizard: ls / tree / df+du / cp / mv /</span></span>
<span class="line"><span>                            rm / edit / stat+chmod</span></span>
<span class="line"><span>ush&gt; files edit /etc/opencube.conf      the full-screen editor</span></span>
<span class="line"><span>ush&gt; cat /etc/opencube.conf              quick read</span></span>
<span class="line"><span>ush&gt; cd /etc &amp;&amp; ls</span></span></code></pre></div><p>The ISO runs from RAM (ramfs root); attach a disk and use <code>disk-tool</code> to partition + format + mount for persistence (<a href="./filesystems.html">filesystems</a>).</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>With the user-mode NIC above:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; dhcp                  or net-tool -&gt; &quot;obtain an address via DHCP&quot;</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2         the QEMU gateway</span></span>
<span class="line"><span>ush&gt; dns example.com</span></span>
<span class="line"><span>ush&gt; wget example.com 80 /</span></span></code></pre></div><p>TLS and SSH are built in: <code>wget</code> negotiates HTTPS, <code>sshd</code> serves the shell, <code>ssh</code> connects out (<a href="./network.html">network</a>).</p><h2 id="shut-down" tabindex="-1">Shut down <a class="header-anchor" href="#shut-down" aria-label="Permalink to &quot;Shut down&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; power                 the wizard (confirmed shutdown/reboot)</span></span>
<span class="line"><span>ush&gt; poweroff              the classic one-shot</span></span></code></pre></div><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li><a href="./mega-apps.html">mega-apps</a> - the wizard / direct / classic contract</li><li><a href="./shell-basics.html">shell-basics</a> - pipes, redirection, scripting</li><li><a href="./update-ota.html">update-ota</a> - the update wizard and the A/B scheme</li><li><a href="./chinese-console.html">chinese-console</a> - <code>lang zh</code> and the IME</li></ul>`,27)])])}const g=s(i,[["render",o]]);export{u as __pageData,g as default};
